<?php
session_start();header('Content-Type: application/json; charset=UTF-8');require_once __DIR__.'/../config/koneksi.php';$d=json_decode(file_get_contents('php://input'),true)?:[];$email=strtolower(trim($d['email']??''));$password=(string)($d['password']??'');
$stmt=$conn->prepare("SELECT u.id,u.nama,u.email,u.password,u.angkatan,u.tahun_lulus,u.foto,j.nama AS fakultas,v.nama AS universitas FROM users u LEFT JOIN jurusan j ON j.id=u.jurusan_id LEFT JOIN universitas v ON v.id=u.universitas_id WHERE u.email=? AND u.role='user'");$stmt->bind_param('s',$email);$stmt->execute();$u=$stmt->get_result()->fetch_assoc();if(!$u||!password_verify($password,$u['password'])){http_response_code(401);echo json_encode(['success'=>false,'message'=>'Email atau password salah']);exit;}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];unset($u['password']);echo json_encode(['success'=>true,'user'=>$u]);
